import{_ as e,c as i,o as r,a0 as t}from"./chunks/framework.DKRgXLPU.js";const _=JSON.parse('{"title":"Fiches d&#39;exercices de préparation mentale","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/fr/exercise-worksheets.md","filePath":"public/downloads/fr/exercise-worksheets.md"}');const a=e({name:"public/downloads/fr/exercise-worksheets.md"},[["render",function(e,_,a,n,o,s){return r(),i("div",null,[..._[0]||(_[0]=[t('<h1 id="fiches-d-39-exercices-de-preparation-mentale" tabindex="-1">Fiches d&#39;exercices de préparation mentale <a class="header-anchor" href="#fiches-d-39-exercices-de-preparation-mentale" aria-label="Permalink to &quot;Fiches d&amp;#39;exercices de préparation mentale&quot;">​</a></h1><p><strong>Académie de Pétanque - Exercices Pratiques</strong></p><hr><h2 id="exercice-1-reflexion-sur-l-39-etat-de-flux" tabindex="-1">Exercice 1 : Réflexion sur l&#39;état de flux <a class="header-anchor" href="#exercice-1-reflexion-sur-l-39-etat-de-flux" aria-label="Permalink to &quot;Exercice 1 : Réflexion sur l&amp;#39;état de flux&quot;">​</a></h2><h3 id="quand-avez-vous-deja-fait-l-39-experience-du-flow" tabindex="-1">Quand avez-vous déjà fait l&#39;expérience du flow ? <a class="header-anchor" href="#quand-avez-vous-deja-fait-l-39-experience-du-flow" aria-label="Permalink to &quot;Quand avez-vous déjà fait l&amp;#39;expérience du flow ?&quot;">​</a></h3><p>Repensez à une fois où vous avez joué votre meilleur jeu de pétanque :</p><p><strong>Décrivez la situation :</strong></p><ul><li>De quel tournoi/match s&#39;agissait-il ?</li><li>Quelles étaient les conditions ?</li><li>Avec qui jouais-tu ?</li></ul><hr><hr><p><strong>Quelles ont été vos impressions ?</strong></p><ul><li>Quel était votre état mental ?</li><li>Comment le temps vous a-t-il paru ?</li><li>À quoi pensiez-vous (ou à quoi ne pensiez-vous pas) ?</li></ul><hr><hr><p><strong>Qu&#39;est-ce qui vous a permis d&#39;y arriver ?</strong></p><ul><li>Qu&#39;as-tu fait avant le match ?</li><li>Qu&#39;est-ce qui était différent ce jour-là ?</li><li>Pouvez-vous recréer l&#39;une de ces conditions ?</li></ul><hr><hr><hr><h2 id="exercice-2-inventaire-du-critique-interieur" tabindex="-1">Exercice 2 : Inventaire du critique intérieur <a class="header-anchor" href="#exercice-2-inventaire-du-critique-interieur" aria-label="Permalink to &quot;Exercice 2 : Inventaire du critique intérieur&quot;">​</a></h2><h3 id="identifiez-votre-critique-interieur" tabindex="-1">Identifiez votre critique intérieur <a class="header-anchor" href="#identifiez-votre-critique-interieur" aria-label="Permalink to &quot;Identifiez votre critique intérieur&quot;">​</a></h3><p><strong>Que dit votre critique intérieure ?</strong></p><p>Énumérez 3 à 5 pensées critiques courantes qui vous viennent à l&#39;esprit pendant la compétition :</p><ol><li><hr></li><li><hr></li><li><hr></li><li><hr></li><li><hr></li></ol><p><strong>Quand apparaît-il ?</strong></p><ul><li>Après des erreurs ? □</li><li>Avant les prises de vue importantes ? □</li><li>Que se passe-t-il lorsque l&#39;on joue contre des adversaires redoutables ? □</li><li>Quand les coéquipiers regardent ? □</li><li>Autre: _______________________________________________</li></ul><hr><h2 id="exercice-3-pratique-du-recadrage" tabindex="-1">Exercice 3 : Pratique du recadrage <a class="header-anchor" href="#exercice-3-pratique-du-recadrage" aria-label="Permalink to &quot;Exercice 3 : Pratique du recadrage&quot;">​</a></h2><h3 id="transformer-le-critique-en-coach" tabindex="-1">Transformer le critique en coach <a class="header-anchor" href="#transformer-le-critique-en-coach" aria-label="Permalink to &quot;Transformer le critique en coach&quot;">​</a></h3><p><strong>Pour chaque pensée de votre critique intérieure, rédigez une reformulation de type coach intérieur :</strong></p><table tabindex="0"><thead><tr><th>Critique intérieure</th><th>Coach intérieur</th></tr></thead><tbody><tr><td>Exemple : « Je fais toujours des erreurs sous pression »</td><td>« J&#39;ai déjà réussi sous pression, je peux le refaire »</td></tr><tr><td>1. _________________________</td><td>_________________________</td></tr><tr><td>2. _________________________</td><td>_________________________</td></tr><tr><td>3. _________________________</td><td>_________________________</td></tr></tbody></table><p><strong>Entraînez-vous à les dire à voix haute</strong></p><hr><h2 id="exercice-4-conception-de-la-routine-de-pre-tir" tabindex="-1">Exercice 4 : Conception de la routine de pré-tir <a class="header-anchor" href="#exercice-4-conception-de-la-routine-de-pre-tir" aria-label="Permalink to &quot;Exercice 4 : Conception de la routine de pré-tir&quot;">​</a></h2><h3 id="creez-votre-routine-personnelle" tabindex="-1">Créez votre routine personnelle <a class="header-anchor" href="#creez-votre-routine-personnelle" aria-label="Permalink to &quot;Créez votre routine personnelle&quot;">​</a></h3><p>Concevez une routine de préparation en 4 étapes qui vous convient :</p><p><strong>Étape 1 : Visualiser</strong></p><ul><li>Que visualiserez-vous exactement ?</li><li>Combien de temps (2-3 secondes) ?</li></ul><hr><p><strong>Étape 2 : Respirez</strong></p><ul><li>Une grande respiration ou trois ?</li><li>Un schéma particulier ?</li></ul><hr><p><strong>Étape 3 : Ancrage</strong></p><ul><li>Quel point d&#39;ancrage physique utiliserez-vous ?</li><li>Toucher la boule ? Position spécifique ?</li></ul><hr><p><strong>Étape 4 : Exécuter</strong></p><ul><li>Quel est votre signal mental ?</li><li>« Confiance » / « Flux » / « Aller » ?</li></ul><hr><p><strong>Effectuez cet exercice 10 fois aujourd&#39;hui</strong></p><hr><h2 id="exercice-5-declencheurs-de-pression" tabindex="-1">Exercice 5 : Déclencheurs de pression <a class="header-anchor" href="#exercice-5-declencheurs-de-pression" aria-label="Permalink to &quot;Exercice 5 : Déclencheurs de pression&quot;">​</a></h2><h3 id="identifiez-vos-points-de-pression" tabindex="-1">Identifiez vos points de pression <a class="header-anchor" href="#identifiez-vos-points-de-pression" aria-label="Permalink to &quot;Identifiez vos points de pression&quot;">​</a></h3><p><strong>Quelles situations vous mettent sous pression ?</strong></p><p>Évaluez chaque élément de 1 (aucune pression) à 10 (pression extrême) :</p><ul><li>Jouer contre des adversaires de haut niveau : ___/10</li><li>Matchs importants du tournoi : ___/10</li><li>Score égal, dernier tir : ___/10</li><li>Après avoir commis une erreur : ___/10</li><li>Quand les coéquipiers regardent : ___/10</li><li>Quand je joue mal : ___/10</li><li>Autre : _________________________ ___/10</li></ul><p><strong>Pour votre déclencheur le mieux noté :</strong></p><p>Quelles sensations physiques ressentez-vous ?</p><hr><p>Quelles pensées vous viennent à l&#39;esprit ?</p><hr><p>Quelle technique allez-vous utiliser ?</p><ul><li>[ ] Réinitialisation en 3 respirations</li><li>[ ] Routine de pré-injection</li><li>[ ] Recadrage</li><li>[ ] Autre: _____________________</li></ul><hr><h2 id="exercice-6-pratique-du-changement-de-mode" tabindex="-1">Exercice 6 : Pratique du changement de mode <a class="header-anchor" href="#exercice-6-pratique-du-changement-de-mode" aria-label="Permalink to &quot;Exercice 6 : Pratique du changement de mode&quot;">​</a></h2><h3 id="planification-vs-execution" tabindex="-1">Planification vs Exécution <a class="header-anchor" href="#planification-vs-execution" aria-label="Permalink to &quot;Planification vs Exécution&quot;">​</a></h3><p><strong>Entraînez-vous à changer de position :</strong></p><p><strong>Phase de planification (avant la prise de vue) :</strong></p><ul><li>Que dois-je analyser ?</li><li>Quelle est ma stratégie ?</li><li>Quel coup vais-je choisir ?</li></ul><p><strong>Phase d&#39;exécution (pendant la prise de vue) :</strong></p><ul><li>Faites le vide dans votre esprit</li><li>Faites confiance à votre corps</li><li>Laisse faire.</li></ul><p><strong>Exercice pratique :</strong></p><p>Prenez 5 photos d&#39;entraînement. Pour chacune :</p><ol><li>Consacrez 10 secondes au mode planification (analyser, décider).</li><li>Prenez 3 respirations pour changer de mode</li><li>Exécuter en mode flux (sans réfléchir)</li></ol><p><strong>Réflexion:</strong></p><ul><li>Avez-vous pu ressentir la différence entre les modes ?</li><li>Le commutateur était-il clair ?</li><li>Quel mode est le plus difficile pour vous ?</li></ul><hr><hr><hr><h2 id="exercice-7-plan-d-39-entrainement-hebdomadaire" tabindex="-1">Exercice 7 : Plan d&#39;entraînement hebdomadaire <a class="header-anchor" href="#exercice-7-plan-d-39-entrainement-hebdomadaire" aria-label="Permalink to &quot;Exercice 7 : Plan d&amp;#39;entraînement hebdomadaire&quot;">​</a></h2><h3 id="theme-de-la-semaine" tabindex="-1">Thème de la semaine <a class="header-anchor" href="#theme-de-la-semaine" aria-label="Permalink to &quot;Thème de la semaine&quot;">​</a></h3><p><strong>Choisissez UNE technique à pratiquer :</strong></p><ul><li>[ ] Réinitialisation en 3 respirations après chaque erreur</li><li>[ ] Routine de préparation avant chaque lancer</li><li>[ ] Recadrer une pensée de la critique intérieure par session</li><li>[ ] Changement de mode d&#39;entraînement</li></ul><p><strong>Pratique quotidienne :</strong></p><table tabindex="0"><thead><tr><th>Jour</th><th>Activité pratique</th><th>Durée</th><th>Notes</th></tr></thead><tbody><tr><td>Lun</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>mar</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Mer</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>jeu</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Ven</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sam</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Soleil</td><td>________________</td><td>___min</td><td>________________</td></tr></tbody></table><hr><h2 id="exercice-8-suivi-des-progres" tabindex="-1">Exercice 8 : Suivi des progrès <a class="header-anchor" href="#exercice-8-suivi-des-progres" aria-label="Permalink to &quot;Exercice 8 : Suivi des progrès&quot;">​</a></h2><h3 id="reflexion-de-fin-de-semaine" tabindex="-1">Réflexion de fin de semaine <a class="header-anchor" href="#reflexion-de-fin-de-semaine" aria-label="Permalink to &quot;Réflexion de fin de semaine&quot;">​</a></h3><p><strong>Qu&#39;avez-vous pratiqué cette semaine ?</strong></p><hr><p><strong>Qu&#39;avez-vous remarqué ?</strong></p><hr><hr><p><strong>Qu&#39;est-ce qui a bien fonctionné ?</strong></p><hr><hr><p><strong>Qu&#39;est-ce qui a été difficile ?</strong></p><hr><hr><p><strong>Que continuerez-vous la semaine prochaine ?</strong></p><hr><hr><p><strong>Qu&#39;allez-vous ajuster ?</strong></p><hr><hr><hr><h2 id="prochaines-etapes" tabindex="-1">Prochaines étapes <a class="header-anchor" href="#prochaines-etapes" aria-label="Permalink to &quot;Prochaines étapes&quot;">​</a></h2><h3 id="poursuivez-votre-developpement" tabindex="-1">Poursuivez votre développement <a class="header-anchor" href="#poursuivez-votre-developpement" aria-label="Permalink to &quot;Poursuivez votre développement&quot;">​</a></h3><p><strong>Ressources disponibles sur carreau.app :</strong></p><ul><li>Modèle d&#39;objectif - Structurez votre développement à long terme</li><li>Modèle de journal intime - Suivre les progrès quotidiens</li><li>La Zone - Plongée au cœur des états de flow</li><li>Force mentale - Gestion avancée du stress</li></ul><p><strong>Continuez à vous entraîner :</strong></p><ul><li>Les compétences mentales nécessitent un entraînement régulier.</li><li>Commencez petit, développez progressivement.</li><li>Suivez vos progrès</li><li>Célébrer les améliorations</li></ul><hr><p><em>Académie de Pétanque - Développement des joueurs élites</em><em>carreau.app</em></p>',113)])])}]]);export{_ as __pageData,a as default};
